import { format } from "date-fns";
import { ExportButton } from "../components/ExportButton";
import { formatEuro } from "../lib/format";
import { useDeleteProduct, useProducts } from "../hooks/useProducts";

export function Inventory({ filter }) {
  const { data: products = [] } = useProducts();
  const del = useDeleteProduct();
  const shown = products.filter((p) => p.name.includes(filter));
  return (
    <>
      <ExportButton products={shown} />
      <table>
        {shown.map((p) => (
          <tr key={p.id}>
            <td>{p.name}</td>
            <td>{formatEuro(p.priceCents)}</td>
            <td>{format(p.updatedAt, "dd/MM/yyyy")}</td>
            <td><button onClick={() => del.mutate(p.id)}>Elimina</button></td>
          </tr>
        ))}
      </table>
    </>
  );
}
